using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Web.Script.Serialization;
using WoWProbe;
class CampaignBundleTests
{
    static int passed,failed;static string root;
    static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static void Assert(bool value,string message="assertion failed"){if(!value)throw new Exception(message);}
    static void Reject(Action action){try{action();}catch(FormatException){return;}catch(InvalidOperationException){return;}catch(IOException){return;}catch(ArgumentException){return;}throw new Exception("unsafe bundle accepted");}
    static string FilePath(string name){return Path.Combine(root,name);}
    static CampaignPlan Plan(){return CampaignDemo.Create();}
    static string Hash(byte[] bytes){using(var sha=SHA256.Create()){var b=new StringBuilder();foreach(byte v in sha.ComputeHash(bytes))b.Append(v.ToString("x2"));return b.ToString();}}
    static Dictionary<string,byte[]> Entries(string path){var d=new Dictionary<string,byte[]>(StringComparer.Ordinal);using(var zip=ZipFile.OpenRead(path))foreach(var e in zip.Entries)using(var s=e.Open())using(var m=new MemoryStream()){s.CopyTo(m);d.Add(e.FullName,m.ToArray());}return d;}
    static void WriteZip(string path,IEnumerable<KeyValuePair<string,byte[]>> files){using(var stream=new FileStream(path,FileMode.Create,FileAccess.Write))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create))foreach(var kv in files){var e=zip.CreateEntry(kv.Key,CompressionLevel.Optimal);using(var s=e.Open())s.Write(kv.Value,0,kv.Value.Length);}}
    static string Good(){string p=FilePath("good-"+Guid.NewGuid().ToString("N")+".wowplan");CampaignBundleStore.Save(p,Plan(),root);return p;}
    static void Rehash(Dictionary<string,byte[]> files){var j=new JavaScriptSerializer();var m=(Dictionary<string,object>)j.DeserializeObject(Encoding.UTF8.GetString(files["manifest.json"]));var list=new List<object>();foreach(var pair in files)if(pair.Key!="manifest.json")list.Add(new{path=pair.Key,length=pair.Value.Length,sha256=Hash(pair.Value)});m["files"]=list;files["manifest.json"]=Encoding.UTF8.GetBytes(j.Serialize(m));}
    static string Mutate(string entry,Func<byte[],byte[]> transform,bool fixManifest)
    {
        var files=Entries(Good());files[entry]=transform(files[entry]);if(fixManifest){var j=new JavaScriptSerializer();var m=(Dictionary<string,object>)j.DeserializeObject(Encoding.UTF8.GetString(files["manifest.json"]));foreach(var x in (object[])m["files"]){var d=(Dictionary<string,object>)x;if((string)d["path"]==entry){d["length"]=files[entry].Length;d["sha256"]=Hash(files[entry]);}}files["manifest.json"]=Encoding.UTF8.GetBytes(j.Serialize(m));}string output=FilePath("mutant-"+Guid.NewGuid().ToString("N")+".wowplan");WriteZip(output,files);return output;
    }
    static void MainTest()
    {
        Test("Unicode bundle preserves reverse loop while clearing every live flag and start index",delegate{var p=Plan();p.Settings.Name="测试方案・回程";p.FarmReverse=p.FarmLoop=true;p.StartIndex=2;p.Settings.BindingsConfirmed=p.Settings.UiConfirmed=p.Settings.AutoResumeConfirmed=p.Battle.BindingsConfirmed=p.Battle.ApproachPositionConfirmed=p.Battle.Calibration.Confirmed=true;string path=FilePath("中文方案.wowplan");CampaignBundleStore.Save(path,p,root);var loaded=CampaignBundleStore.Load(path,FilePath("cache"));var q=loaded.Plan;Assert(q.Settings.Name==p.Settings.Name&&q.FarmReverse&&q.FarmLoop&&q.StartIndex==0);Assert(!q.Settings.BindingsConfirmed&&!q.Settings.UiConfirmed&&!q.Settings.AutoResumeConfirmed&&!q.Battle.BindingsConfirmed&&!q.Battle.ApproachPositionConfirmed&&!q.Battle.Calibration.Confirmed);Assert(p.StartIndex==2&&p.Settings.BindingsConfirmed&&p.Battle.Calibration.Confirmed,"save modified source plan");q.Validate();Assert(Directory.Exists(loaded.AvatarDirectory));});
        Test("all supported route roles survive a complete bundle",delegate{var l=CampaignBundleStore.Load(Good(),FilePath("cache"));Assert(l.Plan.FarmRoute.RouteType=="farm"&&l.Plan.CorpseRoute.RouteType=="corpse_run"&&l.Plan.VendorRoute.RouteType=="vendor_return");});
        Test("disabled interruption routes are omitted rather than silently revived",delegate{var p=Plan();p.Settings.EnableRecovery=p.Settings.EnableVendor=false;string path=FilePath("disabled.wowplan");CampaignBundleStore.Save(path,p,root);var files=Entries(path);Assert(!files.ContainsKey("corpse.json")&&!files.ContainsKey("vendor.json"));var l=CampaignBundleStore.Load(path,FilePath("cache"));Assert(l.Plan.CorpseRoute==null&&l.Plan.VendorRoute==null&&!l.Plan.Settings.EnableRecovery&&!l.Plan.Settings.EnableVendor);});
        Test("referenced PNG portraits travel under canonical name hash paths",delegate{Directory.CreateDirectory(FilePath("avatars"));using(var image=new Bitmap(24,18)){using(var g=Graphics.FromImage(image))g.Clear(Color.FromArgb(12,90,150));image.Save(FilePath("avatars/怪物.png"),ImageFormat.Png);}var p=Plan();p.Battle.Targets[0].AvatarFile="avatars/怪物.png";string original=p.Battle.Targets[0].AvatarFile;string path=FilePath("portrait.wowplan");CampaignBundleStore.Save(path,p,root);var l=CampaignBundleStore.Load(path,FilePath("cache"));string canonical="avatars/"+p.Battle.Targets[0].NameHash.ToString("x8")+".png";Assert(l.Plan.Battle.Targets[0].AvatarFile==canonical&&p.Battle.Targets[0].AvatarFile==original);using(var image=PortraitMatcher.LoadReference(l.AvatarDirectory,l.Plan.Battle.Targets[0]))Assert(image.Size==new Size(24,18)&&image.GetPixel(4,4).B==150);});
        Test("missing or invalid referenced portrait prevents replacement",delegate{string path=Good();var before=File.ReadAllBytes(path);var p=Plan();p.Battle.Targets[0].AvatarFile="avatars/missing.png";Reject(delegate{CampaignBundleStore.Save(path,p,root);});Assert(Hash(File.ReadAllBytes(path))==Hash(before));});
        Test("invalid plan cannot overwrite a previously valid bundle",delegate{string path=Good();var before=File.ReadAllBytes(path);var p=Plan();p.VendorRoute.MapId++;Reject(delegate{CampaignBundleStore.Save(path,p,root);});Assert(Hash(File.ReadAllBytes(path))==Hash(before));});
        Test("file hash mutation is rejected before changing cache",delegate{string cache=FilePath("untouched");Directory.CreateDirectory(cache);File.WriteAllText(Path.Combine(cache,"keep.txt"),"user");string bad=Mutate("farm.json",delegate(byte[] b){b[5]^=1;return b;},false);Reject(delegate{CampaignBundleStore.Load(bad,cache);});Assert(Directory.GetFileSystemEntries(cache).Length==1&&File.ReadAllText(Path.Combine(cache,"keep.txt"))=="user");});
        Test("manifest byte lengths are independently checked",delegate{string bad=Mutate("manifest.json",delegate(byte[] b){return Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(b).Replace("\"length\":", "\"length\":1"));},false);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});});
        Test("manifest schema and normalized fingerprint must match",delegate{foreach(string field in new[]{"schema_version","plan_fingerprint"}){string bad=Mutate("manifest.json",delegate(byte[] b){var j=new JavaScriptSerializer();var m=(Dictionary<string,object>)j.DeserializeObject(Encoding.UTF8.GetString(b));m[field]=field=="schema_version"?(object)2:new string('0',64);return Encoding.UTF8.GetBytes(j.Serialize(m));},false);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});}});
        Test("duplicate manifest JSON keys cannot be hidden by deserialization",delegate{string bad=Mutate("manifest.json",delegate(byte[] b){return Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(b).Replace("\"schema_version\":1","\"schema_version\":1,\"schema_version\":1"));},false);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});});
        Test("invalid field types and route topology are rejected after valid hashes",delegate{foreach(bool topology in new[]{false,true}){string bad=Mutate(topology?"vendor.json":"settings.json",delegate(byte[] b){string text=Encoding.UTF8.GetString(b);return Encoding.UTF8.GetBytes(topology?text.Replace("\"map_id\":900001","\"map_id\":900002"):text.Replace("\"schema_version\":1","\"schema_version\":\"1\""));},true);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});}});
        Test("duplicate and case-colliding archive entries are rejected",delegate{foreach(string name in new[]{"farm.json","Farm.json"}){var files=new List<KeyValuePair<string,byte[]>>(Entries(Good()));files.Add(new KeyValuePair<string,byte[]>(name,Encoding.UTF8.GetBytes("{}")));string bad=FilePath("duplicate-"+name+".wowplan");WriteZip(bad,files);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});}});
        Test("archive path traversal absolute backslash and unknown entries are rejected",delegate{foreach(string name in new[]{"../farm.json","/farm.json","C:/farm.json","avatars\\12345678.png","./farm.json","avatars/","unlisted.json"}){var files=Entries(Good());files.Add(name,new byte[]{1});string bad=FilePath("path-"+Guid.NewGuid().ToString("N")+".wowplan");WriteZip(bad,files);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});}});
        Test("archive symbolic-link metadata cannot publish ordinary-looking files",delegate{var files=Entries(Good());string bad=FilePath("attributes.wowplan");using(var output=File.Create(bad))using(var zip=new ZipArchive(output,ZipArchiveMode.Create))foreach(var kv in files){var e=zip.CreateEntry(kv.Key);if(kv.Key=="farm.json")e.ExternalAttributes=unchecked((int)0xA1FF0000);using(var s=e.Open())s.Write(kv.Value,0,kv.Value.Length);}Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});});
        Test("oversized manifest JSON and entry count stay bounded",delegate{foreach(int kind in new[]{0,1,2}){var files=new List<KeyValuePair<string,byte[]>>(Entries(Good()));if(kind<2){string name=kind==0?"manifest.json":"farm.json";files.RemoveAll(delegate(KeyValuePair<string,byte[]> kv){return kv.Key==name;});files.Add(new KeyValuePair<string,byte[]>(name,new byte[kind==0?65537:2*1024*1024+1]));}else for(int i=0;i<257;i++)files.Add(new KeyValuePair<string,byte[]>("unknown-"+i,new byte[1]));string bad=FilePath("limits-"+kind+".wowplan");WriteZip(bad,files);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});}});
        Test("archive compressed file size is bounded before parsing",delegate{string bad=FilePath("oversize.wowplan");using(var s=File.Create(bad))s.SetLength(16L*1024*1024+1);Reject(delegate{CampaignBundleStore.Load(bad,FilePath("cache"));});});
        Test("separate loads publish different cache folders and never overwrite old assets",delegate{string good=Good();var a=CampaignBundleStore.Load(good,FilePath("cache"));File.WriteAllText(Path.Combine(a.AvatarDirectory,"user-note.txt"),"keep");var b=CampaignBundleStore.Load(good,FilePath("cache"));Assert(a.AvatarDirectory!=b.AvatarDirectory&&File.Exists(Path.Combine(a.AvatarDirectory,"user-note.txt")));});
        Test("expanded byte quota rejects highly compressed assets before cache creation",delegate{var files=Entries(Good());for(int i=0;i<17;i++)files.Add("avatars/"+i.ToString("x8")+".png",new byte[1024*1024]);Rehash(files);string bad=FilePath("expanded.wowplan"),cache=FilePath("expanded-cache");WriteZip(bad,files);bool rejected=false;try{CampaignBundleStore.Load(bad,cache);}catch(FormatException ex){rejected=ex.Message.Contains("expanded data");}Assert(rejected&&!Directory.Exists(cache),"expanded-size guard was not the rejecting boundary");});
        Test("valid file hashes do not bypass PNG dimension validation",delegate{var p=Plan();p.Battle.Targets[0].AvatarFile="avatars/怪物.png";string good=FilePath("png-source.wowplan");CampaignBundleStore.Save(good,p,root);var files=Entries(good);string name="avatars/"+p.Battle.Targets[0].NameHash.ToString("x8")+".png";files[name][16]=0;files[name][17]=0;files[name][18]=2;files[name][19]=1;Rehash(files);string bad=FilePath("png-dimensions.wowplan"),cache=FilePath("bad-png-cache");WriteZip(bad,files);Reject(delegate{CampaignBundleStore.Load(bad,cache);});Assert(!Directory.Exists(cache));});
        Test("externally injected live confirmations are sanitized even with valid manifest hashes",delegate{var files=Entries(Good());foreach(string name in new[]{"settings.json","battle.json"}){string text=Encoding.UTF8.GetString(files[name]).Replace("\"bindings_confirmed\":false","\"bindings_confirmed\":true").Replace("\"ui_confirmed\":false","\"ui_confirmed\":true").Replace("\"auto_resume_confirmed\":false","\"auto_resume_confirmed\":true").Replace("\"approach_position_confirmed\":false","\"approach_position_confirmed\":true").Replace("\"confirmed\":false","\"confirmed\":true");files[name]=Encoding.UTF8.GetBytes(text);}Rehash(files);string path=FilePath("injected-flags.wowplan");WriteZip(path,files);var p=CampaignBundleStore.Load(path,FilePath("cache")).Plan;Assert(!p.Settings.BindingsConfirmed&&!p.Settings.UiConfirmed&&!p.Settings.AutoResumeConfirmed&&!p.Battle.BindingsConfirmed&&!p.Battle.ApproachPositionConfirmed&&!p.Battle.Calibration.Confirmed);});
        Test("required file omission cannot publish or repair an existing cache",delegate{var files=Entries(Good());files.Remove("vendor.json");Rehash(files);string bad=FilePath("missing-vendor.wowplan"),cache=FilePath("missing-cache");WriteZip(bad,files);Reject(delegate{CampaignBundleStore.Load(bad,cache);});Assert(!Directory.Exists(cache));});
    }
    static int Main(){root=Path.Combine(Path.GetTempPath(),"wow-bundle-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);MainTest();Console.WriteLine("Campaign bundle tests: "+passed+" passed, "+failed+" failed; no input backend.");return failed==0?0:1;}
}
